import * as THREE from 'three'
import type { WorldGraphNode } from './worldGraph'

export const createNodeObject = (node: WorldGraphNode) => {
  const scale = 4;
  const baseW = 160;
  const baseH = 48;

  const textLen = node.title.length;
  const width = Math.max(baseW, baseW + (textLen - 6) * 14);
  const height = baseH;

  const canvas = document.createElement('canvas');
  canvas.width = width * scale;
  canvas.height = height * scale;
  const ctx = canvas.getContext('2d')!;
  ctx.scale(scale, scale);

  // 圆角矩形
  const radius = 12;
  ctx.beginPath();
  ctx.moveTo(radius, 0);
  ctx.lineTo(width - radius, 0);
  ctx.quadraticCurveTo(width, 0, width, radius);
  ctx.lineTo(width, height - radius);
  ctx.quadraticCurveTo(width, height, width - radius, height);
  ctx.lineTo(radius, height);
  ctx.quadraticCurveTo(0, height, 0, height - radius);
  ctx.lineTo(0, radius);
  ctx.quadraticCurveTo(0, 0, radius, 0);
  ctx.closePath();

  // 渐变
  const gradient = ctx.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, node.color);
  gradient.addColorStop(1, shadeColor(node.color, -15));
  ctx.fillStyle = gradient;
  ctx.fill();

  // 文字
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 16px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(node.title, width / 2, height / 2 + 1);

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;

  const material = new THREE.SpriteMaterial({
    map: texture,
    transparent: true,
    depthTest: false,
  });
  const sprite = new THREE.Sprite(material);

  const worldHeight = 10;
  const worldWidth = worldHeight * (width / height);
  sprite.scale.set(worldWidth, worldHeight, 1);

  return sprite;
};

const shadeColor = (hex: string, percent: number): string => {
  const num = parseInt(hex.replace('#', ''), 16);
  const r = Math.max(0, Math.min(255, (num >> 16) + percent));
  const g = Math.max(0, Math.min(255, ((num >> 8) & 0x00ff) + percent));
  const b = Math.max(0, Math.min(255, (num & 0x0000ff) + percent));
  return '#' + ((r << 16) | (g << 8) | b).toString(16).padStart(6, '0');
};

import type { CardDetail, CardSummary, Relation } from '@/api/types/world'
import { CardTypeMeta, type CardType } from '@/views/世界观管理/card_type'
import { getEmbeddedCardIds } from './worldPresentation'

// 保留图谱与编辑器原有的配色差异，其余类型使用共用元信息。
const graphColors: Record<string, string> = { organization: '#7c3aed', creature: '#84cc16', concept: '#6366f1' }
export const getGraphTypeColor = (type: string) => graphColors[type] || CardTypeMeta[type as CardType]?.color || '#64748b'

// 关系类型配色（按字符串哈希取稳定色，保证同一种关系颜色一致）
const relationPalette = ['#ef4444', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6', '#ec4899', '#14b8a6', '#f97316', '#6366f1', '#84cc16']
export function getRelationTypeColor(type: string) {
  if (!type) return '#94a3b8'
  let hash = 0
  for (const ch of type) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0
  return relationPalette[hash % relationPalette.length]
}

export interface WorldGraphNode { id: string; title: string; type: string; color: string; x?: number; y?: number; z?: number }
export interface WorldGraphEdge { source: string; target: string; label: string; color: string; width: number; isEmbed: boolean }

export function buildWorldGraph(cards: CardSummary[], relations: Relation[], findDetail: (id: string) => CardDetail | null | undefined) {
  const nodes: WorldGraphNode[] = cards.map(card => ({ id: card.id, title: card.title, type: card.type, color: getGraphTypeColor(card.type) }))
  const ids = new Set(cards.map(card => card.id))
  const relationKeys = new Set<string>()
  const links: WorldGraphEdge[] = []
  for (const relation of relations) {
    if (!ids.has(relation.sourceCardId) || !ids.has(relation.targetCardId)) continue
    relationKeys.add(`${relation.sourceCardId}__${relation.targetCardId}`)
    links.push({ source: relation.sourceCardId, target: relation.targetCardId, label: relation.relationType,
      color: getRelationTypeColor(relation.relationType), width: 1.5, isEmbed: false })
  }
  for (const card of cards) {
    for (const target of getEmbeddedCardIds(findDetail(card.id), true)) {
      if (target === card.id || !ids.has(target)) continue
      if (relationKeys.has(`${card.id}__${target}`)) continue
      links.push({ source: card.id, target, label: '引用', color: '#94a3b8', width: 0.8, isEmbed: true })
    }
  }
  return { nodes, links }
}

export function getNodeCameraPosition(node: Pick<WorldGraphNode, 'x' | 'y' | 'z'>) {
  const target = { x: node.x || 0, y: node.y || 0, z: node.z || 0 }
  const length = Math.hypot(target.x, target.y, target.z)
  if (!length) return { position: { x: 0, y: 0, z: 100 }, target }
  const ratio = 1 + 100 / length
  return { position: { x: target.x * ratio, y: target.y * ratio, z: target.z * ratio }, target }
}

export function getGraphCameraPosition(nodes: WorldGraphNode[], aspect: number, fov: number) {
  const axes = ['x', 'y', 'z'] as const
  const center = { x: 0, y: 0, z: 0 }
  for (const axis of axes) {
    const values = nodes.map(node => node[axis] || 0)
    center[axis] = values.length ? (Math.min(...values) + Math.max(...values)) / 2 : 0
  }
  // 用节点位置计算范围，并为标签留出边距。
  const radius = Math.max(30, ...nodes.map(node => Math.hypot(...axes.map(axis => (node[axis] || 0) - center[axis])) + 30))
  const halfFov = fov * Math.PI / 360
  const angle = Math.min(halfFov, Math.atan(Math.tan(halfFov) * Math.max(aspect, 0.1)))
  const distance = radius / Math.sin(angle)
  return { target: center, position: { x: center.x + distance * 0.6, y: center.y + distance * 0.36, z: center.z + distance * 0.715 } }
}

import { onMounted, onBeforeUnmount, ref, watch, type Ref } from 'vue'
import ForceGraph3D, { type ForceGraph3DInstance, type LinkObject } from '3d-force-graph'
import type { WorldGraphNode, WorldGraphEdge } from '@/utils/worldGraph'
import { getNodeCameraPosition, getGraphCameraPosition } from '@/utils/worldGraph'
import { createNodeObject } from '@/utils/worldGraphSprite'

type GraphLink = Omit<WorldGraphEdge, 'source' | 'target'> & LinkObject<WorldGraphNode>
interface GraphControls { autoRotate: boolean; autoRotateSpeed: number; enableDamping: boolean; dampingFactor: number }

/** 组件只提供图数据和选中回调，3D 实例、尺寸监听与释放在此处管理。 */
export function useWorldGraph(container: Ref<HTMLElement | null>,
  data: Ref<{ nodes: WorldGraphNode[]; links: WorldGraphEdge[] }>, onSelect: (id: string) => void) {
  const loading = ref(false)
  const autoRotate = ref(true)
  let graph: ForceGraph3DInstance<WorldGraphNode, GraphLink> | null = null
  let resizeObserver: ResizeObserver | undefined
  let themeObserver: MutationObserver | undefined
  let needsInitialFit = true

  function syncTheme() {
    if (container.value) graph?.backgroundColor(getComputedStyle(container.value).getPropertyValue('--bg-main').trim())
  }

  function refresh() {
    // 图库会修改坐标与边的端点，传入副本避免污染 Store 派生数据。
    graph?.graphData({ nodes: data.value.nodes.map(node => ({ ...node })), links: data.value.links.map(link => ({ ...link })) })
  }
  function resize() {
    if (graph && container.value) graph.width(container.value.clientWidth).height(container.value.clientHeight)
  }
  function toggleRotate() {
    autoRotate.value = !autoRotate.value
    if (graph) (graph.controls() as GraphControls).autoRotate = autoRotate.value
  }
  function resetCamera() {
    if (!graph || !container.value) return
    const { position, target } = getGraphCameraPosition(graph.graphData().nodes,
      container.value.clientWidth / Math.max(container.value.clientHeight, 1), 50)
    graph.cameraPosition(position, target, 500)
  }

  onMounted(() => {
    if (!container.value) return
    loading.value = true
    try {
      graph = new ForceGraph3D(container.value) as unknown as ForceGraph3DInstance<WorldGraphNode, GraphLink>
      graph.width(container.value.clientWidth).height(container.value.clientHeight)
        .graphData({ nodes: [], links: [] })
        .nodeThreeObject(createNodeObject).nodeThreeObjectExtend(false)
        .linkColor(link => link.color).linkWidth(link => link.width).linkOpacity(0.6)
        .linkDirectionalArrowLength(link => link.isEmbed ? 0 : 3.5)
        .linkDirectionalArrowRelPos(1).linkDirectionalArrowColor(link => link.color)
        .linkLabel(link => {
          const label = document.createElement('span')
          label.textContent = link.label
          return label
        })
        .onNodeClick(node => {
          onSelect(node.id)
          const { position, target } = getNodeCameraPosition(node)
          graph?.cameraPosition(position, target, 1000)
        })
        .onBackgroundClick(() => onSelect(''))
        .onEngineStop(() => {
          if (needsInitialFit && data.value.nodes.length) { needsInitialFit = false; resetCamera() }
        })
        .d3AlphaDecay(0.02).d3VelocityDecay(0.3).warmupTicks(80).cooldownTicks(120)
      Object.assign(graph.controls(), { autoRotate: autoRotate.value, autoRotateSpeed: 0.5, enableDamping: true, dampingFactor: 0.1 })
      refresh()
      syncTheme()
      resizeObserver = new ResizeObserver(resize)
      resizeObserver.observe(container.value)
      themeObserver = new MutationObserver(syncTheme)
      themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] })
    } finally { loading.value = false }
  })
  watch(data, refresh, { deep: true })
  onBeforeUnmount(() => {
    resizeObserver?.disconnect()
    themeObserver?.disconnect()
    try { graph?._destructor() }
    catch (error) { console.warn('释放世界观图谱失败:', error) }
    finally { graph = null }
  })
  return { loading, autoRotate, refresh, toggleRotate, resetCamera }
}

